<!--
  @changelog
  | 版本   | 变更说明                                                        |
  | v0.1.0 | 通用拖拽分隔条：支持横向(改宽)/纵向(改高)、min/max 约束、双击重置 |
  /@changelog

  @author v_weiqinlin

  ## 用法

  ```vue
  <!-- 纵向分隔条（拖动改变上下两个面板的高度） -->
  <Splitter direction="horizontal" v-model="topHeight" :min="100" :max="600" :default-value="300" />

  <!-- 横向分隔条（拖动改变左右两个面板的宽度） -->
  <Splitter direction="vertical" v-model="leftWidth" :min="240" :max="800" :default-value="360" />
  ```

  - `direction='horizontal'`：分隔条**水平摆放**（一条横线），拖动方向是**上下**，改变的是「目标元素的高度」
  - `direction='vertical'`：分隔条**垂直摆放**（一条竖线），拖动方向是**左右**，改变的是「目标元素的宽度」
  - 双击分隔条重置回 `defaultValue`
-->
<template>
  <div
    class="splitter"
    :class="[`splitter-${direction}`, { active: dragging }]"
    @mousedown.prevent="onMouseDown"
    @dblclick="onDoubleClick"
    role="separator"
    :aria-orientation="direction === 'horizontal' ? 'horizontal' : 'vertical'"
    title="拖动调整尺寸（双击重置）"
  >
    <div class="splitter-handle"></div>
  </div>
</template>

<script setup lang="ts">
import { ref, onBeforeUnmount } from 'vue';

const props = withDefaults(
  defineProps<{
    /** horizontal=水平分隔条(拖动改变高度); vertical=垂直分隔条(拖动改变宽度) */
    direction: 'horizontal' | 'vertical';
    /** 当前值（高度或宽度，px） */
    modelValue: number;
    /** 最小值，默认 100 */
    min?: number;
    /** 最大值，默认 9999 */
    max?: number;
    /** 双击时重置到的默认值；不传则不响应双击 */
    defaultValue?: number;
  }>(),
  { min: 100, max: 9999 },
);

const emit = defineEmits<{
  (e: 'update:modelValue', v: number): void;
  (e: 'drag-start'): void;
  (e: 'drag-end'): void;
}>();

const dragging = ref(false);
let startPos = 0;
let startValue = 0;

const onMouseDown = (e: MouseEvent) => {
  dragging.value = true;
  startPos = props.direction === 'horizontal' ? e.clientY : e.clientX;
  startValue = props.modelValue;
  // 拖拽期间禁止文本选择 + 改光标
  document.body.style.userSelect = 'none';
  document.body.style.cursor = props.direction === 'horizontal' ? 'row-resize' : 'col-resize';
  document.addEventListener('mousemove', onMouseMove);
  document.addEventListener('mouseup', onMouseUp);
  emit('drag-start');
};

const onMouseMove = (e: MouseEvent) => {
  if (!dragging.value) return;
  const cur = props.direction === 'horizontal' ? e.clientY : e.clientX;
  const delta = cur - startPos;
  const next = clamp(startValue + delta, props.min, props.max);
  if (next !== props.modelValue) emit('update:modelValue', next);
};

const onMouseUp = () => {
  if (!dragging.value) return;
  dragging.value = false;
  document.body.style.userSelect = '';
  document.body.style.cursor = '';
  document.removeEventListener('mousemove', onMouseMove);
  document.removeEventListener('mouseup', onMouseUp);
  emit('drag-end');
};

const onDoubleClick = () => {
  if (props.defaultValue !== undefined) {
    emit('update:modelValue', clamp(props.defaultValue, props.min, props.max));
  }
};

const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v));

// 安全清理
onBeforeUnmount(() => {
  if (dragging.value) onMouseUp();
});
</script>

<style scoped>
.splitter {
  position: relative;
  flex-shrink: 0;
  background: transparent;
  transition: background var(--me-trans-fast);
  z-index: 5;
}

/* 水平分隔条（一条横线，拖动改高） */
.splitter-horizontal {
  width: 100%;
  height: 6px;
  cursor: row-resize;
  margin: -3px 0; /* 负 margin 让分隔条覆盖在两个面板边界上，不占视觉空间 */
}

/* 垂直分隔条（一条竖线，拖动改宽） */
.splitter-vertical {
  width: 6px;
  height: 100%;
  cursor: col-resize;
  margin: 0 -3px;
}

/* 内部 1px 高亮线，hover/active 时变色 */
.splitter-handle {
  position: absolute;
  background: var(--me-border);
  transition: background var(--me-trans-fast);
}

.splitter-horizontal .splitter-handle {
  left: 0;
  right: 0;
  top: 50%;
  height: 1px;
  transform: translateY(-50%);
}

.splitter-vertical .splitter-handle {
  top: 0;
  bottom: 0;
  left: 50%;
  width: 1px;
  transform: translateX(-50%);
}

.splitter:hover .splitter-handle,
.splitter.active .splitter-handle {
  background: var(--me-primary);
}

.splitter-horizontal:hover .splitter-handle,
.splitter-horizontal.active .splitter-handle {
  height: 2px;
  box-shadow: 0 0 0 1px rgba(99, 102, 241, 0.2);
}

.splitter-vertical:hover .splitter-handle,
.splitter-vertical.active .splitter-handle {
  width: 2px;
  box-shadow: 0 0 0 1px rgba(99, 102, 241, 0.2);
}
</style>
