<template>
  <div class="color-picker" :class="{ focused: isFocused }">
    <!-- hex 输入框（左） -->
    <input
      class="cp-input me-mono"
      type="text"
      :value="currentValue"
      @input="onTextInput"
      @focus="isFocused = true"
      @blur="onTextBlur"
      placeholder="#ffffff"
      spellcheck="false"
    />

    <!-- 分隔线 -->
    <span class="cp-divider"></span>

    <!-- 色块（右，点击触发原生调色盘） -->
    <label class="cp-swatch-wrap" title="点击打开调色盘">
      <span class="cp-swatch" :style="{ background: normalizedColor }"></span>
      <input
        class="cp-native"
        type="color"
        :value="normalizedColor"
        @input="onNativeInput"
      />
    </label>
  </div>
</template>

<script setup lang="ts">
import { ref, computed } from 'vue';

const props = withDefaults(
  defineProps<{
    modelValue?: string;
  }>(),
  { modelValue: '#ffffff' },
);

const emit = defineEmits<{
  (e: 'update:modelValue', value: string): void;
}>();

const currentValue = ref(props.modelValue);
const isFocused = ref(false);

/** 规范化颜色值：保证传给 native picker 的是合法 hex */
const normalizedColor = computed(() => {
  const v = (currentValue.value || '').trim();
  if (/^#([0-9a-f]{3})$/i.test(v)) {
    return ('#' + v[1] + v[1] + v[2] + v[2] + v[3] + v[3]).toLowerCase();
  }
  if (/^#([0-9a-f]{6})$/i.test(v)) {
    return v.toLowerCase();
  }
  return '#ffffff';
});

const onNativeInput = (e: Event) => {
  const val = (e.target as HTMLInputElement).value;
  currentValue.value = val;
  emit('update:modelValue', val);
};

const onTextInput = (e: Event) => {
  currentValue.value = (e.target as HTMLInputElement).value;
};

const onTextBlur = () => {
  isFocused.value = false;
  emit('update:modelValue', currentValue.value);
};
</script>

