<template>
  <div class="field-row" :class="{ inline }">
    <div class="field-header">
      <div class="field-header-left">
        <label class="field-label">
          {{ label }}
          <span v-if="required" class="required-mark" title="必填字段">*</span>
        </label>
        <span v-if="hint" class="field-hint me-mono">{{ hint }}</span>
      </div>
      <button
        v-if="removable"
        class="field-remove-btn"
        title="移除该字段"
        @click="emit('remove')"
      >
        <X :size="12" />
      </button>
    </div>
    <div class="field-control">
      <slot />
    </div>
  </div>
</template>

<script setup lang="ts">
import { X } from 'lucide-vue-next';

defineProps<{
  label: string;
  hint?: string;
  inline?: boolean;
  /** 是否为必填字段（label 旁显示红色 *） */
  required?: boolean;
  /** 是否显示移除按钮（仅可选字段已添加时显示） */
  removable?: boolean;
}>();

const emit = defineEmits<{
  /** 用户点击移除按钮 */
  (e: 'remove'): void;
}>();
</script>

