    <!-- 标题栏 + 添加按钮 -->
    <div class="panel-header">
      <span class="panel-title">{{ title }}</span>
      <div v-if="!isEmpty" class="add-wrapper" v-show="addableOptions.length">
        <button
          ref="addBtnRef"
          class="add-btn"
          @click.stop="toggleAddMenu"
          :class="{ active: showAddMenu }"
        >
          <Plus :size="13" :stroke-width="2.5" />
          <span>添加</span>
          <ChevronDown :size="12" class="add-caret" />
        </button>
        <!--
          下拉传送到 body：
          1) 摆脱祖先 .scene-tree-wrap / .panel-header 的 overflow:hidden 裁切
          2) fixed 定位 = 视口坐标，按按钮 getBoundingClientRect 计算 top/right
          3) max-height + overflow-y:auto 在选项过多时启用滚动
        -->
        <Teleport to="body">
          <Transition name="me-dropdown-add">
            <div
              v-if="showAddMenu"
              class="add-dropdown meta-editor-scope"
              :style="dropdownStyle"
              @click.stop
            >
              <div class="dropdown-section">可添加控件</div>
              <button
                v-for="opt in addableOptions"
                :key="opt.id"
                class="add-option"
                :class="{ added: opt.added }"
                :disabled="opt.added"
                @click="onAdd(opt)"
              >
                <span class="opt-label">{{ opt.label }}</span>
                <span class="opt-desc">{{ opt.desc }}</span>
                <Check v-if="opt.added" :size="12" class="opt-check" />
              </button>
