      <div class="guide-actions">
        <button class="guide-btn primary" @click="$emit('action', 'new')">
          <FilePlus :size="16" />
          <div class="guide-btn-text">
            <div class="guide-btn-title">新建项目</div>
            <div class="guide-btn-desc">从空白骨架开始</div>
          </div>
          <span class="guide-shortcut">Ctrl+N</span>
        </button>

        <button class="guide-btn" @click="$emit('action', 'import')">
          <Upload :size="16" />
          <div class="guide-btn-text">
            <div class="guide-btn-title">导入文件</div>
            <div class="guide-btn-desc">打开本地 meta.json</div>
          </div>
          <span class="guide-shortcut">Ctrl+O</span>
        </button>

        <button class="guide-btn ghost" @click="$emit('action', 'load-example')">
          <Sparkles :size="16" />
          <div class="guide-btn-text">
