    <!-- 正常态：场景层级树 -->
    <div v-else class="tree-section">
      <div class="section-title">
        <ChevronRight :size="12" />
        <span>场景层级</span>
        <span class="section-count">{{ visibleWidgets.length }}</span>
      </div>
      <div class="tree-list">
        <button
          v-for="widget in visibleWidgets"
          :key="widget.id"
          class="tree-item"
          :class="{ selected: widget.id === selectedId }"
          @click="$emit('select', widget.id)"
        >
          <span class="item-label">{{ widget.label || widget.id }}</span>
          <span v-if="widget.required" class="me-tag">默认</span>
          <span
            v-else
            class="item-remove"
            title="移除"
            @click.stop="$emit('remove', widget.id)"
          >
            <X :size="12" />
          </span>
        </button>
      </div>
    </div>
  </div>
</template>

<script setup lang="ts">
import { ref, computed, onMounted, onBeforeUnmount } from 'vue';
import {
  Plus,
  ChevronDown,
  ChevronRight,
  Check,
  X,
  FolderOpen,
  FilePlus,
  Upload,
  Sparkles,
} from 'lucide-vue-next';
import type { EditorRules, WidgetSchema } from '../schema/types';
import { keyToLabel } from '../schema/infer';

const props = withDefaults(
  defineProps<{
    selectedId: string | null;
    /** 整个 JSON 数据 */
    value: any;
    /** 规则集 */
    rules: EditorRules;
    /** 是否处于空白引导态（meta 完全为空） */
    isEmpty?: boolean;
  }>(),
  { isEmpty: false },
);

const emit = defineEmits<{
  (e: 'select', id: string): void;
  (e: 'add', id: string): void;
  (e: 'remove', id: string): void;
  (e: 'action', action: 'new' | 'import' | 'export' | 'load-example'): void;
}>();

const showAddMenu = ref(false);
const addBtnRef = ref<HTMLButtonElement | null>(null);
/**
 * 下拉的 fixed 定位样式（视口坐标）。
 *
 * 由按钮 getBoundingClientRect 实时计算：
 * - top = 按钮底部 + 6px 间距
 * - right = 视口宽度 - 按钮右边距，让下拉与按钮右对齐
 *
 * showAddMenu 翻为 true 前由 toggleAddMenu 主动刷新一次；
 * 打开期间监听 resize/scroll 同步刷新（最多 60fps，避免抖动）。
 */
const dropdownStyle = ref<Record<string, string>>({});

function recalcDropdownPos(): void {
  const btn = addBtnRef.value;
  if (!btn) return;
  const rect = btn.getBoundingClientRect();
  dropdownStyle.value = {
    position: 'fixed',
    top: `${rect.bottom + 6}px`,
    right: `${window.innerWidth - rect.right}px`,
    // max-height 留 24px 余量给底部 padding，避免贴底
    maxHeight: `${Math.max(180, window.innerHeight - rect.bottom - 24)}px`,
  };
}
const title = computed(() => props.rules.treeTitle ?? '操作菜单');

/**
 * 当前可见 widgets（树中显示）的算法
 *
 * **三类节点**：
 * 1. 真实节点：规则中 id === 顶层 JSON key（rootPath = '' 或 = id）
 * 2. 虚拟节点：规则中 rootPath 指向嵌套路径（如 'initial.player'）
 *    - rootPath 第一段视为"被消费的顶层 key"
 *    - 当某顶层 key 的所有数据子 key 都被规则消费完，该顶层 key 不再独立显示
 *      （否则数据会有"两个入口编辑同一处"的歧义）
 * 3. 自动推断节点：JSON 顶层有但规则未声明且未被消费的 key
 *
 * **required 与可见性**：
 * - required=true 的规则节点（含虚拟节点）即使数据缺失也显示，让用户能"添加默认数据"
 * - required=false 的规则节点仅当 rootPath 数据存在时显示
 */

/** 检查路径是否在 value 中存在（点分割） */
function pathExists(value: any, path: string): boolean {
  if (!path || !value || typeof value !== 'object') return false;
  const parts = path.split('.');
  let cur = value;
  for (const p of parts) {
    if (cur == null || typeof cur !== 'object') return false;
    if (!(p in cur)) return false;
    cur = cur[p];
  }
  return true;
}

/**
 * 计算"被规则消费的子路径集合"（按顶层 key 分组）
 *
 * 例：规则中有 player(rootPath='initial.player')、camera(rootPath='initial.camera')
 * 返回：{ initial: Set { 'player', 'camera' } }
 *
 * **两种贡献来源**（v0.9.8 起）：
 * 1) widget.rootPath 含 '.'（如 'initial.player'）→ 第一段 / 第二段贡献
 * 2) widget.fields[].path 含 '.'（如 camera widget 的 'initial.camera'）→ 同上
 *    此分支用于 rootPath='' 的"跨多路径 widget"，让其字段路径也能贡献消费语义。
 */
function computeConsumedSubKeys(rules: EditorRules): Map<string, Set<string>> {
  const consumed = new Map<string, Set<string>>();

  const recordPath = (rawPath: string): void => {
    const p = (rawPath || '').trim();
    if (!p) return;
    // 切分时同时兼容数组索引语法 'a.b[0]'，但本场景的字段路径只用点分割
    const parts = p.split('.');
    if (parts.length < 2) return;
    const topKey = parts[0];
    const subKey = parts[1].replace(/\[\d+\]$/, '');
    if (!topKey || !subKey) return;
    if (!consumed.has(topKey)) consumed.set(topKey, new Set());
    consumed.get(topKey)!.add(subKey);
  };

  for (const w of rules.widgets) {
    // 1) widget rootPath 贡献
    recordPath(w.rootPath || '');
    // 2) widget fields[].path 贡献（覆盖 rootPath='' 跨多路径 widget 的场景）
    if (Array.isArray(w.fields)) {
      for (const f of w.fields) recordPath(f.path || '');
    }
  }
  return consumed;
}

const visibleWidgets = computed<WidgetSchema[]>(() => {
  const data = props.value;
  const isObj = data && typeof data === 'object';

  // 1. 收集"被消费的顶层 key 子集"
  const consumed = computeConsumedSubKeys(props.rules);

  // 2. 处理规则中的所有 widget（保持规则顺序）
  const list: WidgetSchema[] = [];
  const ruleConsumedTopKeys = new Set<string>(); // 已经由规则虚拟节点占用的顶层 key
  const seenIds = new Set<string>();

  for (const w of props.rules.widgets) {
    if (seenIds.has(w.id)) continue;

    const rp = (w.rootPath || '').trim();
    const isVirtual = rp.includes('.'); // rootPath 含 '.' 即虚拟节点
    const topKey = rp ? rp.split('.')[0] : w.id;

    // 显示判定
    let show = false;
    if (w.required) {
      show = true; // required 始终显示，即便数据缺失
    } else if (w.visibleInTree) {
      show = w.visibleInTree(data);
    } else {
      // 默认按 rootPath（或 id）数据是否存在
      const checkPath = rp || w.id;
      show = isObj && pathExists(data, checkPath);
    }

    if (show) {
      list.push({ ...w, label: w.label ?? w.id });
      seenIds.add(w.id);
      if (isVirtual) ruleConsumedTopKeys.add(topKey);
    }
  }

  // 3. 自动推断：JSON 顶层 key 中没被规则覆盖、且未被虚拟节点完全消费的，追加为节点
  if (props.rules.autoInferUnknownTopKeys !== false && isObj) {
    const declaredIds = new Set(props.rules.widgets.map((w) => w.id));

    for (const k of Object.keys(data)) {
      if (declaredIds.has(k)) continue; // 已被规则用作 widget id（含真实节点）
      if (seenIds.has(k)) continue;

      // 若 k 是某虚拟节点的顶层 key，判断是否被完全消费
      if (consumed.has(k)) {
        const consumedSubs = consumed.get(k)!;
        const dataSubs = data[k] && typeof data[k] === 'object' ? Object.keys(data[k]) : [];
        const allConsumed = dataSubs.length > 0 && dataSubs.every((s) => consumedSubs.has(s));
        if (allConsumed) continue; // 完全消费 → 隐藏
      }

      list.push({
        id: k,
        label: keyToLabel(k) || k,
        rootPath: k,
        required: false,
      });
      seenIds.add(k);
    }
  }

  return list;
});

/** 可添加项：所有非 required 且当前未在树中的 widget */
interface AddOption {
  id: string;
  label: string;
  desc: string;
  added: boolean;
}

const addableOptions = computed<AddOption[]>(() => {
  const visibleIds = new Set(visibleWidgets.value.map((w) => w.id));
  return props.rules.widgets
    .filter((w) => !w.required)
    .map((w) => ({
      id: w.id,
      label: w.label ?? w.id,
      desc: w.desc ?? '',
      added: visibleIds.has(w.id),
    }));
});

const toggleAddMenu = () => {
  const next = !showAddMenu.value;
  if (next) recalcDropdownPos();
  showAddMenu.value = next;
};

const onAdd = (opt: AddOption) => {
  if (opt.added) return;
  emit('add', opt.id);
  showAddMenu.value = false;
};

// 点击外部关闭
const closeOnOutside = (e: MouseEvent) => {
  const target = e.target as HTMLElement;
  // 注意：dropdown 已 teleport 到 body，不再在 .add-wrapper 内部
  if (target.closest('.add-wrapper') || target.closest('.add-dropdown')) return;
  showAddMenu.value = false;
};

// 视口变化时如果下拉打开则刷新位置
const onWinChange = () => {
  if (showAddMenu.value) recalcDropdownPos();
};

onMounted(() => {
  document.addEventListener('click', closeOnOutside);
  window.addEventListener('resize', onWinChange);
  window.addEventListener('scroll', onWinChange, true);
});
onBeforeUnmount(() => {
  document.removeEventListener('click', closeOnOutside);
  window.removeEventListener('resize', onWinChange);
  window.removeEventListener('scroll', onWinChange, true);
});
</script>

