<template>
  <div class="me-select" :class="{ open: isOpen }" ref="rootEl">
    <button
      class="me-select-trigger"
      type="button"
      @click.stop="toggle"
    >
      <span class="trigger-text" :class="{ placeholder: !selectedOption }">
        {{ selectedOption ? selectedOption.label : placeholder }}
      </span>
      <ChevronDown :size="14" class="trigger-caret" />
    </button>

    <Transition name="me-select-pop">
      <div v-if="isOpen" class="me-select-panel" @click.stop>
        <div
          v-for="opt in options"
          :key="opt.value"
          class="me-select-option"
          :class="{ active: opt.value === modelValue }"
          @click="onSelect(opt)"
        >
          <span class="opt-text">{{ opt.label }}</span>
          <Check v-if="opt.value === modelValue" :size="13" class="opt-check" />
        </div>
      </div>
    </Transition>
  </div>
</template>

<script setup lang="ts">
import { ref, computed, onMounted, onBeforeUnmount } from 'vue';
import { ChevronDown, Check } from 'lucide-vue-next';

interface Option {
  value: string;
  label: string;
}

const props = withDefaults(
  defineProps<{
    modelValue?: string;
    options: Option[];
    placeholder?: string;
  }>(),
  { placeholder: '请选择' },
);

const emit = defineEmits<{
  (e: 'update:modelValue', value: string): void;
}>();

const isOpen = ref(false);
const rootEl = ref<HTMLElement>();

const selectedOption = computed(() =>
  props.options.find((o) => o.value === props.modelValue),
);

const toggle = () => {
  isOpen.value = !isOpen.value;
};

const onSelect = (opt: Option) => {
  emit('update:modelValue', opt.value);
  isOpen.value = false;
};

const closeOnOutside = (e: MouseEvent) => {
  if (rootEl.value && !rootEl.value.contains(e.target as Node)) {
    isOpen.value = false;
  }
};

onMounted(() => document.addEventListener('click', closeOnOutside));
onBeforeUnmount(() => document.removeEventListener('click', closeOnOutside));
</script>

